  /**
   * allProductAvailability iterates over GET /v2/publicCloud/project/{projectId}/reference/productAvailability (Get product availability).
   *
   * It yields one item at a time, and gets the next page only when the loop reaches it. An
   * error is thrown and stops the loop.
   *
   * Product availability
   *
   * Returns the products available to this Public Cloud project, grouped by product type.
   *
   * This is read-only reference data: the response is computed from the OVHcloud commercial catalog
   * combined with the project's entitlements and its quota usage. It does not reflect existing
   * resources and triggers no OpenStack call.
   *
   * The response is an array with one entry per product type, in this order: `INSTANCE`, `VOLUME`,
   * `LOADBALANCER`, `GATEWAY`, `FLOATING_IP`, `PUBLIC_IP`, `VOLUME_SNAPSHOT`, `VOLUME_BACKUP`,
   * `INSTANCE_SNAPSHOT`, `SHARE`, `SHARE_SNAPSHOT`, `OBJECT_STORAGE`, `SWIFT`. Each type group
   * carries its `models`. Each model carries the `locations` where it is sold to the project, in
   * the regions activated on the project and in those the project can activate. Each location
   * reports its availability zones, `regionActivated`, a `quotaStatus` with the quota resources
   * that block it (`quotaLimitedBy`) and, for the `INSTANCE` type only, a `stockStatus` per
   * availability zone.
   *
   * `links` point to related operations: a `SPECS` link on a model leads to the reference route
   * describing it, and a location whose `quotaStatus` is `INSUFFICIENT` carries a `QUOTA` link.
   *
   * Every filter is optional: `type` keeps the group of that product type only, `region` the
   * locations of that region (letter case ignored), `name` the models with exactly that name and
   * `nameContains` the models whose name contains that value (letter case ignored).
   *
   * Requires the IAM action publicCloudProject:apiovh:reference/productAvailability/get.
   *
   * @param projectId - Project ID
   * @param params - the optional parameters
   * @param options - the options of this call: signal, timeout, headers
   * @returns each {@link models.PublicCloudReferenceProductAvailability}, one at a time: loop with `for await`
   * @throws ForbiddenError when the policy lacks an IAM action this call requires
   * @example
   * for await (const item of client.publicCloud.allProductAvailability(projectId)) console.log(item);
   */
  allProductAvailability(
    projectId: string,
    params?: {
      /** Optional exact model name filter, for example b3-8 */
      name?: string | undefined;
      /** Optional model name filter keeping the names that contain this value, letter case ignored */
      nameContains?: string | undefined;
      /** Optional region filter, letter case ignored */
      region?: string | undefined;
      /** Optional product type filter */
      type?: models.PublicCloudReferenceProductTypeEnum | undefined;
    },
    options?: RequestOptions,
  ): AsyncIterable<models.PublicCloudReferenceProductAvailability> {
    return this._pages(
      OPS.allProductAvailability,
      {
        path: { projectId: projectId },
        query: [
          ["name", params?.name],
          ["nameContains", params?.nameContains],
          ["region", params?.region],
          ["type", params?.type],
        ],
      },
      options,
    );
  }

